<div class="page-head"><div><h1>Relatórios</h1><p>Consultas por período, médico e especialidade.</p></div>
<form method="get" style="display:flex;gap:8px;flex-wrap:wrap"><input type="date" name="de" value="<?= e($de) ?>" style="padding:8px;border:1px solid var(--sage-line);border-radius:7px"><input type="date" name="ate" value="<?= e($ate) ?>" style="padding:8px;border:1px solid var(--sage-line);border-radius:7px"><button class="btn btn-secondary">Aplicar</button><a class="btn btn-primary" href="/recepcao/relatorios.csv?de=<?= e($de) ?>&ate=<?= e($ate) ?>">⬇ Exportar CSV</a></form></div>
<div class="stat-row"><?php $t = array_sum(array_column($status, 'total')); foreach ([[$t,'Consultas no período'],[$taxa === null ? '—' : $taxa . '%','Taxa de comparecimento']] as [$n,$l]): ?><div class="card stat-card"><div class="stat-num"><?= e($n) ?></div><div class="stat-label"><?= $l ?></div></div><?php endforeach; ?>
<?php foreach ($status as $s): ?><div class="card stat-card"><div class="stat-num"><?= (int)$s['total'] ?></div><div class="stat-label"><?= e(STATUS_LABEL[$s['status']]) ?></div></div><?php endforeach; ?></div>
<div class="grid2" style="align-items:start"><div class="card pad"><div class="section-title">Por especialidade</div><?php $mx = max(1, ...array_map('intval', array_column($esp, 'total') ?: [1])); foreach ($esp as $r): ?><div class="bar-row"><span style="width:130px"><?= e($r['nome']) ?></span><div class="bar-track"><div class="bar-fill" style="width:<?= round(100 * $r['total'] / $mx) ?>%"></div></div><b><?= (int)$r['total'] ?></b></div><?php endforeach; ?></div>
<div class="card"><table class="table"><thead><tr><th>Médico</th><th>Total</th><th>Realizadas</th><th>Faltas</th></tr></thead><tbody><?php foreach ($medicos as $r): ?><tr><td><?= e($r['nome']) ?></td><td><?= (int)$r['total'] ?></td><td><?= (int)$r['realizadas'] ?></td><td><?= (int)$r['faltas'] ?></td></tr><?php endforeach; ?></tbody></table></div></div>
